        <div class="topbar-actions">
          <button class="icon-button export-conversation hidden" id="exportConversationBtn" type="button" title="Export conversation" aria-label="Export conversation">${j(`download`,17)}</button>
          <button class="artifact-reopen hidden" id="artifactReopenBtn" type="button" title="Open artifact" aria-label="Open artifact">${j(`file`,16)}<span id="artifactReopenLabel">Artifact</span></button>
          <button class="quiet-chip" id="runtimeChip" title="Runtime status"><span class="runtime-dot"></span><span id="runtimeText">Local</span></button>
        </div>
